CREATE COLUMN TABLE "TEST_AP"."OFAR" ("DocEntry" INTEGER CS_INT NOT NULL , "DocNum" INTEGER CS_INT NOT NULL , "Series" INTEGER CS_INT, "PostDate" LONGDATE CS_LONGDATE, "AssetDate" LONGDATE CS_LONGDATE, "Ref" NVARCHAR(32), "Comments" NVARCHAR(254), "JrnlMemo" NVARCHAR(254), "DprArea" NVARCHAR(15), "TransId" INTEGER CS_INT, "Handwrtten" NVARCHAR(1) DEFAULT 'N', "PIndicator" NVARCHAR(10) NOT NULL , "DocDate" LONGDATE CS_LONGDATE, "BPLId" INTEGER CS_INT, "BPLName" NVARCHAR(100), "VatRegNum" NVARCHAR(32), "RevalPerc" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OFAR_INDEX" ON "TEST_AP"."OFAR" ( "DocNum" ASC, "PIndicator" ASC )